18	type StateRecorder struct {
19		SavedMessages []*protos.SavedMessage
20	}
21	
22	func (sr *StateRecorder) Save(message *protos.SavedMessage) error {
23		sr.SavedMessages = append(sr.SavedMessages, message)
24		return nil
25	}
26	
27	func (*StateRecorder) Restore(_ *View) error {
28		panic("should not be used")
29	}
